}

void fill_counts(int u, int *cnt, int offset) {
    cnt[offset]++;
    for (Edge *e = adj[u]; e; e = e->next) {
        int v = e->to;
        if (v != parent[u]) {
            fill_counts(v, cnt, offset+1);
        }
    }
