typedef unsigned long long ULL;

typedef struct Edge {
    int to, next;
} Edge;

typedef struct Vec {
    ULL *a;
    int sz, cap;
} Vec;

static void vec_init(Vec *v) {
    v->a = NULL;
    v->sz = 0;
    v->cap = 0;
}

static void vec_reserve(Vec *v, int nc) {
    if (nc <= v->cap) return;
    v->cap = nc;
    v->a = (ULL*)realloc(v->a, sizeof(ULL) * v->cap);
}

static void vec_push(Vec *v, ULL x) {
    if (v->sz == v->cap) {
        int nc = (v->cap == 0 ? 4 : v->cap * 2);
        vec_reserve(v, nc);
    }
    v->a[v->sz++] = x;
}

static const ULL BASE = 1000003ULL;

static void merge_small_to_large(Vec *big, Vec *small) {
    if (small->sz == 0) return;
    if (big->sz < small->sz) {
        Vec tmp = *big;
        *big = *small;
        *small = tmp;
    }
    for (int i = 0; i < small->sz; i++) {
        big->a[i + 1] += small->a[i];
    }
}

static int cmp_ull(const void *a, const void *b) {
    ULL x = *(const ULL*)a;
    ULL y = *(const ULL*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Edge *edges = (Edge*)malloc(sizeof(Edge) * (N > 1 ? (N - 1) : 1));
    int *head = (int*)malloc(sizeof(int) * (N + 1));
    int *parent = (int*)malloc(sizeof(int) * (N + 1));
    int *order = (int*)malloc(sizeof(int) * (N + 1));
    int *stack = (int*)malloc(sizeof(int) * (N + 1));
    Vec *dp = (Vec*)malloc(sizeof(Vec) * (N + 1));
    ULL *hashv = (ULL*)malloc(sizeof(ULL) * (N + 1));

    for (int i = 1; i <= N; i++) {
        head[i] = -1;
        vec_init(&dp[i]);
    }

    for (int i = 2; i <= N; i++) {
        int p;
        scanf("%d", &p);
        parent[i] = p;
        edges[i - 2].to = i;
        edges[i - 2].next = head[p];
        head[p] = i - 2;
    }
    parent[1] = 0;

    int top = 0, ordsz = 0;
    stack[top++] = 1;
    while (top) {
        int u = stack[--top];
        order[ordsz++] = u;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            stack[top++] = edges[e].to;
        }
    }

    for (int idx = ordsz - 1; idx >= 0; idx--) {
        int u = order[idx];

        int first = 1;
        Vec cur;
        vec_init(&cur);

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (first) {
                cur = dp[v];
                first = 0;
            } else {
                merge_small_to_large(&cur, &dp[v]);
            }
        }

        if (first) {
            vec_push(&cur, 1ULL);
        } else {
            if (cur.sz == cur.cap) vec_reserve(&cur, cur.cap ? cur.cap * 2 : 4);
            memmove(cur.a + 1, cur.a, sizeof(ULL) * cur.sz);
            cur.a[0] = 1ULL;
            cur.sz++;
        }

        dp[u] = cur;

        ULL h = 1469598103934665603ULL;
        for (int i = 0; i < dp[u].sz; i++) {
            h = h * BASE + dp[u].a[i] + 97ULL;
        }
        h = h * BASE + (ULL)dp[u].sz + 1237ULL;
        hashv[u] = h;
    }

    qsort(hashv + 1, N, sizeof(ULL), cmp_ull);

    long long ans = 0;
    long long cnt = 1;
    for (int i = 2; i <= N; i++) {
        if (hashv[i] == hashv[i - 1]) {
            cnt++;
        } else {
            ans += cnt * (cnt - 1) / 2;
            cnt = 1;
        }
    }
    ans += cnt * (cnt - 1) / 2;

    printf("%lld\n", ans);

    for (int i = 1; i <= N; i++) free(dp[i].a);
    free(edges);
    free(head);
    free(parent);
    free(order);
    free(stack);
    free(dp);
    free(hashv);

    return 0;
}

